function getArtworks() {
    try {
        const data = localStorage.getItem(STORAGE_KEYS.artworks);
        if (data) {
            const parsed = JSON.parse(data);
            if (Array.isArray(parsed) && parsed.length > 0) return parsed;
        }
    } catch (e) {
        console.error('Error reading artworks:', e);
    }
    const presets = getInitialPresetArtworks();
    saveArtworks(presets, true);
    return presets;
}

function saveArtworks(artworks, skipCloudSync = false) {
    try {
        localStorage.setItem(STORAGE_KEYS.artworks, JSON.stringify(artworks));
    } catch (e) {
        console.error('QuotaExceeded:', e);
    }

    // Only sync to Firebase if explicitly allowed AND artworks has actual content
    if (!skipCloudSync && typeof firebaseDb !== 'undefined' && firebaseDb && Array.isArray(artworks) && artworks.length > 0) {
        const artObj = {};
        artworks.forEach(a => {
            if (a && a.id) artObj[a.id] = a;
        });
        firebaseDb.ref('artworks').set(artObj).catch(err => {
            console.warn('Firebase saveArtworks sync error:', err);
        });
    }
}

function generateId() {
    return 'art_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);
}

